def solution(input_data):
    import sys
    input_str = input_data.read()
    lines = input_str.strip().split('\n')

    n, m, k = map(int, lines[0].split())
    adj = [[] for _ in range(n + 1)]
    edges = []

    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)
        edges.append((u, v))

    # Try to find k cycles first
    def find_cycles():
        visited = [False] * (n + 1)
        parent = [0] * (n + 1)
        cycle_found = [[] for _ in range(k + 1)]
        found_cycles = 0

        # Try to find cycles using DFS
        def dfs(u, d, path):
            nonlocal found_cycles
            visited[u] = True
            path.append(u)

            for v in adj[u]:
                if v == parent[u]:
                    continue
                if visited[v]:
                    # Found a cycle
                    cycle = []
                    in_cycle = False
                    for node in path:
                        if node == v:
                            in_cycle = True
                        if in_cycle:
                            cycle.append(node)
                    if len(cycle) >= 3:
                        # Check if length is not divisible by 3
                        if len(cycle) % 3 != 0:
                            found_cycles += 1
                            cycle_found[found_cycles] = cycle
                    return  # Continue searching for more cycles
                if len(path) < n and found_cycles < k:
                    parent[v] = u
                    dfs(v, d + 1, path)

            path.pop()

        # Try starting from each node to find cycles
        for start_node in range(1, n + 1):
            if found_cycles >= k:
                break
            visited = [False] * (n + 1)
            parent = [0] * (n + 1)
            dfs(start_node, 0, [])
            if found_cycles >= k:
                break

        if found_cycles >= k:
            # Add representative vertex for each cycle - first vertex in cycle path
            for i in range(1, k + 1):
                if len(cycle_found[i]) < 3:
                    continue
                cycle_found[i] = cycle_found[i][1:] + [cycle_found[i][1]]  # Fix cycle format

            c1 = []
            c2 = []
            for i in range(1, k + 1):
                if not cycle_found[i]:
                    print("-1" if found_cycles >= k else "")
                    return None
                c = list(cycle_found[i])
                if len(c) >= 3:
                    c1.append(len(c))
                    c2.append(c)

            # Ensure each cycle has a representative (first node in case)
            rep_nodes = [c[0] for c in c2]

            return "CYCLES\n" + "\n".join(f"{len(c)}\n{' '.join(map(str,c))}" for c in c2)

        return None

    # Try to find a path
    def find_path():
        visited = [False] * (n + 1)

        def dfs(u, d, path):
            visited[u] = True
            if d >= n // k:
                return path[:d+1]  # Return path with enough vertices

            for v in adj[u]:
                if not visited[v]:
                    path.append(v)
                    result = dfs(v, d + 1, path)
                    if result and len(result) >= n // k:
                        return result
                    path.pop()

            visited[u] = False
            return None

        for start in range(1, n + 1):
            if find_path():
                return "PATH\n" + str(len(find_path_start(start))) + "\n" + " ".join(map(str, find_path_start(start)))

        return None

    def find_path_start(start):
        visited = [False] * (n + 1)
        path = [start]
        visited[start] = True

        def dfs(u):
            for v in adj[u]:
                if not visited[v]:
                    path.append(v)
                    if len(path) >= n // k:
                        return
                    dfs(v)
                    path.pop()

        dfs(start)
        return path if path and len(path) >= n // k else None

    # First try to find cycles
    result = find_cycles()
    if result:
        return result

    # If cycles don't work, try path
    result = find_path()
    if result:
        return result

    return "-1"

