    lines = input_str.strip().split('\n')
    k, n, m = map(int, lines[0].split())
    skills = list(map(int, lines[1].split()))

    improvements = []
    for i in range(n):
        parts = list(map(int, lines[2 + i].split()))
        t = parts[0]
        idx = parts[1] - 1
        b = parts[2]
        improvements.append((t, idx, b, i + 1))

    used_skills = set()
    result_indexes = []
    final_skills = skills.copy()

    for _ in range(m):
        best_increase = -float('inf')
        best_improvement = None

        for t, idx, b, original_idx in improvements:
            if idx in used_skills:
                continue

            current_skill_value = final_skills[idx]

            if t == 1:
                new_skill_value = b
            elif t == 2:
                new_skill_value = current_skill_value + b
            elif t == 3:
                new_skill_value = current_skill_value * b
            else:
                continue

            current_product = 1
            for s in final_skills:
                current_product *= s

            new_product = 1
            for i in range(k):
                if i == idx:
                    new_product *= new_skill_value
                else:
                    new_product *= final_skills[i]

            increase = new_product - current_product
            if increase > best_increase:
                best_increase = increase
                best_improvement = (t, idx, b, original_idx)

        if best_improvement is None:
            break

        t, idx, b, original_idx = best_improvement
        used_skills.add(idx)
        final_skills[idx] = best_improvement[0]
        result_indexes.append(original_idx)

    result = f"{len(result_indexes)}\n{' '.join(map(str, result_indexes))} "
    return result

