def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:]]

    visited = [[False] * m for _ in range(n)]
    rooms = []

    # Find all rooms by connected components
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                room = []
                stack = [(i, j)]
                visited[i][j] = True
                while stack:
                    r, c = stack.pop()
                    room.append((r, c))
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '.' and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                rooms.append(room)

    # For each room, check if it's already rectangular. If not, we need to decide:
    # Either keep some walls to maintain separate rectangular rooms, or merge rooms.
    # The optimal approach: For each room with bounding box, mark ALL cells in the box as '.'
    # This ensures each room is rectangular. However, adjacent rooms might merge - that's OK.
    # But we need to check: after this transformation, are all rooms rectangular?

    # Actually, simpler approach: For each room, make its bounding box all '.' 
    # This greedily converts walls inside rooms. Then check if this maintains rectangularity.

    for room in rooms:
        r_coords = [r for r, c in room]
        c_coords = [c for r, c in room]
        min_r, max_r = min(r_coords), max(r_coords)
        min_c, max_c = min(c_coords), max(c_coords)

        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                if grid[r][c] == '*':
                    grid[r][c] = '.'

    # Convert back to string
    result = []
    for i in range(n):
        result.append(''.join(grid[i]) + '\n')

    return ''.join(result)

