    def dist_sq(p1, p2):
        return (p1[0]-p2[0])**2 + (p1[1]-p2[1])**2 + (p1[2]-p2[2])**2

    # 3D Minimum Enclosing Ball - Welzl's Algorithm
    def welzl(points, r_points):
        if not r_points:
            if not points:
                return [[0.0, 0.0, 0.0], 0.0]  # center, radius
            dc = points[0]
            return [dc, 0.0]

        p = points[-1]
        remaining = points[:-1]

        sph = welzl(remaining, r_points)

        if dist_sq(p, sph[0]) <= sph[1] + 1e-9:
            return sph

        return welzl_helper(p, [p] + r_points)

    def welzl_helper(p, r_points):
        n = len(r_points)
