def solution(input_data):
    lines = input_data.strip().split('\n')
    n = int(lines[0])

    if n == 1:
        return str(n)

    adj = [[] for _ in range(n + 1)]
    for i in range(1, n):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (n + 1)

    # dp[u][s] = maximum product from subtree rooted at u, where u belongs to a component of size s
    # Returns a dictionary mapping size -> max_product

    def get_subtree_size(u, p):
        size = 1
        for v in adj[u]:
            if v != p and not visited[v]:
                size += get_subtree_size(v, u)
        visited[u] = True
        return size

    def compute_dp(u, p):
        if not visited[u]:
            visited[u] = True
            # Size 1 means the component is just u itself (not connected to any children)
            # But we can optionally connect to children to increase size

            # Start with just u
            dp_u = {1: 1}
            subtree_size = 0
            for v in adj[u]:
                if v != p and not visited[v]:
                    subtree_size += get_subtree_size(v, u)

            # Compute DP for each child
            for v in adj[u]:
                if v != p and not visited[v]:
                    dp_v = compute_dp(v, u)

                    # Merge dp_v into dp_u (knapsack-style)
                    new_dp = {}
                    size_u = 0

                    for prev_size, prev_prod in dp_u.items():
                        size_u += prev_size

                        # For each possible size from child v
                        for child_size, child_prod in dp_v.items():
                            new_final_size = size_u + child_size

                            # Option 1: Keep the edge (u, v) - component sizes add up
                            new_prod = prev_prod * child_prod
                            if new_final_size not in new_dp or new_dp[new_final_size] < new_prod:
                                new_dp[new_final_size] = new_prod

                        size_u += prev_size

                        # Option 2: Cut the edge (u, v) - child's component is independent
                        # The max product from child's subtree is the max in dp_v
                        max_child_prod = max(dp_v.values())

                        # No size change from child, product multiplies
                        new_prod_cut = prev_prod * max_child_prod
                        if size_u not in new_dp or new_dp[size_u] < new_prod_cut:
                            new_dp[size_u] = new_prod_cut

                    dp_u = new_dp

            return dp_u

        return None

    # We'll do a fresh DFS to compute DP properly
    visited = [False] * (n + 1)

    def dfs_dp(u, p):
        # dp[u][s] = max product from subtree of u, where u is in a component of size s
        dp_u = {}
        dp_u[1] = 1

        for v in adj[u]:
            if v != p:
                child_dp, _ = dfs_dp(v, u)

                new_dp = {}

                # Try all combinations
                for su, spu in dp_u.items():
                    for sv, spv in child_dp.items():
                        # Keep edge: sizes add, products multiply
                        newSize = su + sv
                        newProd = spu * spv
                        if newSize not in new_dp or new_dp[newSize] < newProd:
                            new_dp[newSize] = newProd

                # Cut edge: child's max product is standalone
                max_child = max(child_dp.values())
                for su, spu in dp_u.items():
                    newSize = su
                    newProd = spu * max_child
                    if newSize not in new_dp or new_dp[newSize] < newProd:
                        new_dp[newSize] = newProd

                dp_u = new_dp

        return dp_u

    result_dp = dfs_dp(1, 0)
    ans = max(result_dp.values())
    return str(ans)

MOD = 998244853

def solution(s):
    n, m = map(int, s.strip().split())

    if n == 0:
        return "0\n"

    # Precompute binomial coefficients
    fact = [1] * (n + m + 1)
    inv = [1] * (n + m + 1)

    for i in range(1, n + m + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    inv[n + m] = pow(fact[n + m], MOD - 2, MOD)
    for i in range(n + m - 1, -1, -1):
        inv[i] = (inv[i + 1] * (i + 1)) % MOD

    def C(nk):
        if nk < 0 or nk > n + m:
            return 0
        return fact[nk] * inv[nk] % MOD

    # Compute sum_{i=0}^{n-1} C(n+m, i)
    ans = 0
    for i in range(n):
        ans = (ans + C(i)) % MOD

    return f"{ans}\n"

def solution(input_str):
    """
    Solves the path restoration problem based on vertex visit parity constraints.

    The key insight is that in any path:
    - Start and end vertices contribute 1 to their visit counts (odd)
    - All internal vertices in the path contribute 2 to their visit counts (even)
    - We can traverse edges multiple times to adjust visit counts

    Since we can revisit vertices, we need to strategically construct paths.
    """
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1"

    n, m = map(int, lines[0].split())

    if m == 0:
        # No edges, check if all x_i are 0
