            return "0\n"
        else:
            return "-1"

    edges = []
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        edges.append((u, v))

    parities = list(map(int, lines[m + 1].split()))

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i] and adj[i]:
            comp = []
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                comp.append(node)
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            components.append(comp)

    # Build BFS function for finding paths
    def bfs(start, end, adj):
        from collections import deque
        if start == end:
            return [start]
        dist = {start: 0}
        parent = {start: None}
        queue = deque([start])
        while queue and end not in dist:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor not in dist:
                    dist[neighbor] = dist[node] + 1
                    parent[neighbor] = node
                    queue.append(neighbor)
        if end not in dist:
            return None
        path = []
        node = end
        while node is not None:
            path.append(node)
            node = parent[node]
        return path[::-1]

    # Build a path for each component to satisfy its internal constraints
    # Then combine them appropriately

    # Strategy: Count how many odd-position vertices we have
    # In a valid path, at most 2 vertices can have odd visit count (start and end)
    # For other vertices, we need even visits

    # Build the path by processing odd-parity vertices
    odd_vertices = [i + 1 for i, p in enumerate(parities) if p == 1]
    need_odd = len(odd_vertices)

    # If we need exactly 0 odd vertices, return empty path
    if need_odd == 0:
        return "0\n"

    # If we need exactly 2 odd vertices, we can potentially use them as start/end
    if need_odd == 2:
        # Simple case: just find a path between the two odd vertices within their component
