                return paths_to_output(len(path), path)
            elif odd_vertices[0] not in components[0] and odd_vertices[1] in components[0]:
                # In different components
                path1 = [odd_vertices[0]]
                path2 = bfs(odd_vertices[1], odd_vertices[0], adj)
                if path2 is None:
                    return "-1"
                return paths_to_output(len(path1) + len(path2) - 1, path1 + path2[1:])
        elif odd_vertices[0] in components[1] or odd_vertices[1] in components[1]:
            if odd_vertices[0] in components[1] and odd_vertices[1] in components[1]:
                path = bfs(odd_vertices[0], odd_vertices[1], adj)
