        # Fallback: try pairing differently
        return construct_path_with_cycles(m, adj, parities, n)
    else:
        # For more than 2 odd vertices, we need to create cycles
        # Visit odd vertices by going back and forth (adds 2 visits = even)
        # But we need exactly the right parity, so use internal cycling

        # Simple solution: go back and forth on edges for each odd vertex
        path = []
        odd_idx = set(odd_vertices)

        for i in range(1, n + 1):
            if i in odd_idx:
                path.append(i)
