def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].strip().split()))

    def is_gp(a):
        length = len(a)
        if length <= 2:
            return True

        # Handle all zeros case
        if all(x == 0 for x in a):
            return True

        # If first element is zero, all others must be too
        if a[0] == 0:
            return all(x == 0 for x in a)

        # First two non-zero elements determine the ratio
        r = a[1] / a[0]

        # Check consistency for all consecutive pairs
        for i in range(1, length - 1):
            if a[i] == 0:
                continue
            if i + 1 < length and a[i+1] != 0:
                if abs(a[i+1] / a[i] - r) > 1e-9:
                    return False

        return True

    # Check if already a GP
    if is_gp(arr):
        return "0\n"

    # Try deleting each element
    for i in range(n):
        new_arr = arr[:i] + arr[i+1:]
        if is_gp(new_arr):
            return "1\n"

    return "2\n"

import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    operations = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        t = int(parts[0])
        x_prime = int(parts[1])
        y = int(parts[2])
        x = x_prime / 100000.0
        operations.append((t, x, y))

    # ans[j] = earliest time-step to reach banana count j
    ans = [-1] * (m + 1)

    # Initially k=0 is reachable at time 0
    reachable = {0}

    for i, (t, x, y) in enumerate(operations, 1):
        new_reachable = set()
        seen_this_step = set()
        mark_updated = False

        for k in reachable:
            if t == 1:
                # Type 1: k := ⌈k + a*x⌉ for 0 ≤ a ≤ y
                # Since k is always integer, ⌈k + a*x⌉ = k + a*⌈x⌉
                ceil_x = int(math.ceil(x))
                for a in range(y + 1):
                    new_k = k + a * ceil_x
                    if new_k <= m:
                        if new_k not in seen_this_step:
                            seen_this_step.add(new_k)
                            new_reachable.add(new_k)
                            if ans[new_k] == -1:
                                ans[new_k] = i
                                mark_updated = True
            else:
                # Type 2: k := ⌈k * x⌉, apply up to y times
                for a in range(y + 1):
                    if k <= m and k not in seen_this_step:
                        seen_this_step.add(k)
                        new_reachable.add(k)
                        if ans[k] == -1:
                            ans[k] = i
                            mark_updated = True
                    else:
                        break

                # Apply the operation up to y-1 more times
                for a in range(1, y + 1):
                    curr_k = k
                    for _ in range(a):
                        curr_k = int(math.ceil(curr_k * x))

                    if curr_k <= m:
                        if curr_k not in seen_this_step:
                            seen_this_step.add(curr_k)
                            new_reachable.add(curr_k)
                            if ans[curr_k] == -1:
                                ans[curr_k] = i
                                mark_updated = True
                    else:
                        break

        reachable = new_reachable

        # Check if we've found all reachable targets
        if all(v != -1 for v in ans[1:m+1]):
            break

    # Build output string
    result = ' '.join(str(ans[i]) for i in range(1, m + 1))
    return result


