def solution(input_str):
    lines = input_str.strip().split('\n')

    # Parse first line
    header = lines[0].split()
    N, M, K = int(header[0]), int(header[1]), int(header[2])

    # Parse transformers
    transformers = []
    for i in range(1, K + 1):
        parts = lines[i].split()
        x, y, d, t, e = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
        transformers.append({'x': x, 'y': y, 'd': d, 't': t, 'e': e})

    # Helper to get transformer position at time absolute_t
    def get_position(x, y, d, start_t, abs_t):
        if abs_t < start_t:
            return None  # Not started yet
        rel_t = abs_t - start_t
        step = rel_t % 4
        tx, ty = x, y
        if step == 0:
            tx, ty = x, y
        elif step == 1:
            tx, ty = x + d, y - d
        elif step == 2:
            tx, ty = x + d, y
        elif step == 3:
            tx, ty = x, y + d
        return (tx, ty)

    # Find transformers at each cell (r, c) at time t = r + c
    # Collect energy costs per cell per time (only one query per cell!)
    cell_energy = {}

    for r in range(N):
        for c in range(M):
            t = r + c
            for trans in transformers:
                pos = get_position(trans['x'], trans['y'], trans['d'], trans['t'], t)
                if pos == (r, c):
                    energy = trans['e']
                    key = (r, c)
                    if key not in cell_energy:
                        cell_energy[key] = 0
                    cell_energy[key] += energy
                    break  # Each transformer only counted once at position

    # Handle transformers that might be at (r,c) at multiple times in cycle
    # Though since we only visit each (r,c) at time r+c, we only care once
    cell_energy = {}  # Redefine properly
    for r in range(N):
        for c in range(M):
            t = r + c
            total_energy = 0
            for trans in transformers:
                pos = get_position(trans['x'], trans['y'], trans['d'], trans['t'], t)
                if pos == (r, c):
                    total_energy += trans['e']
            cell_energy[(r, c)] = total_energy

    # DP: dp[r][c] = min energy to reach (r, c)
    # dp[r][c] = cell_energy[(r, c)] + min(dp[r-1][c], dp[r][c-1])

    dp = [[float('inf')] * M for _ in range(N)]

    for r in range(N):
        for c in range(M):
            energy = cell_energy[(r, c)]
            if r == 0 and c == 0:
                dp[r][c] = energy
                continue

            min_prev = float('inf')
            if r > 0:
                min_prev = min(min_prev, dp[r-1][c])
            if c > 0:
                min_prev = min(min_prev, dp[r][c-1])

            dp[r][c] = min_prev + energy

    return str(dp[N-1][M-1]) + '\n'


