    best = 0

    def dfs(pos, cnt, mask):
        nonlocal best

        if pos == m:
            best = max(best, cnt)
            return

        # Pruning: remaining count can't exceed best
        if cnt + (m - pos) <= best:
            return

        # Try not including current node
        dfs(pos + 1, cnt, mask)

