import sys
from collections import deque

MOD = 1000000007

def get_moves(x, y):
    """Return all positions a knight can move from (x, y)"""
    return [
        (x + 1, y + 2), (x + 1, y - 2),
        (x - 1, y + 2), (x - 1, y - 2),
        (x + 2, y + 1), (x + 2, y - 1),
        (x - 2, y + 1), (x - 2, y - 1)
    ]

def solve(k, n, deleted):
    """Solve the knight movement problem"""
    if k == 0:
        return 1

    visited = {}
    queue = deque()

    # Map each reachable position to its distance from (0,0)
    visited[(0, 0)] = 0
    queue.append((0, 0))

    max_reachable = {(0, 0): 0}

    count = 0

    # Process BFS
    while queue and max_reachable.get((queue[0][0], queue[0][1]), 0) < k:
        x, y = queue.popleft()
        dist = visited[(x, y)]

        if dist < k:
            for nx, ny in get_moves(x, y):
                if (nx, ny) not in deleted and (nx, ny) not in visited:
                    visited[(nx, ny)] = dist + 1
                    queue.append((nx, ny))

    # Count all reachable positions (no more than k moves)
    count = len(visited)
    return str(count % MOD)

def solution(input_str):
    """Parse input and solve the problem"""
    lines = input_str.strip().split('\n')
    k, n = map(int, lines[0].split())

    deleted = set()
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        deleted.add((x, y))

    return solve(k, n, deleted)

