    maxx, maxy, w = map(int, parts)
    if w <= 0 or maxx < 1 or maxy < 1:
        return '-1'

    rev = [0] * (max(maxx, maxy) + 1)

    def rev_func(n):
        # Compute reversed number with leading zeros removed
        return int(str(n)[::-1])

    # Precompute rev values
    for i in range(1, max(maxx, maxy) + 1):
        rev[i] = rev_func(i)

    # Count lucky pairs for given x and y
    # A ticket (a, b) is lucky if a * b == rev(a) * rev(b)
    # Equivalent to: a / rev(a) == rev(b) / b

    # For efficient counting, precompute rev[i]
    # Group numbers by rev[i]

    def count_lucky(x, y):
        """Count how many lucky tickets exist in [1,x] x [1,y]"""
        if x == 0 or y == 0:
            return 0

        # Strategy: for each a in [1,x], count b in [1,y] where a*b = rev(a)*rev(b)
        # This is: b * rev(a) == a * rev(b) -> b / rev(b) == a / rev(a)
        # Let's group by the "reverse ratio"

        count = 0

        # We need to be careful about performance
        # For x=22, y=111, we can iterate
        if x <= 200 and y <= 200:
            for a in range(1, x + 1):
                for b in range(1, y + 1):
                    if a * b == rev[a] * rev[b]:
                        count += 1
            return count
        else:
            # Optimization needed for larger values
            # Precompute ratio groups
            ratio_groups = defaultdict(list)
            for i in range(1, x + 1):
                ratio_groups[float(i) / rev[i]].append(i)

            target_map = defaultdict(list)
            for i in range(1, y + 1):
                target_map[float(i) / rev[i]].append(i)

            count = 0
            for ratio, a_list in ratio_groups.items():
                target_ratio = 1.0 / ratio
                if target_ratio in target_map:
                    for i in a_list:
                        for j in target_map[target_ratio]:
                            # Verify exact integer equality to avoid float precision issues
                            if i * j == rev[i] * rev[j]:
                                count += 1
            return count

    # Try different (x, y) combinations to find minimum x*y with at least w lucky tickets
    best_result = None
    best_product = float('inf')

    # Since we want minimum x*y, try smaller values first
    # Sort by x first, then y
    for x in range(1, maxx + 1):
        for y in range(1, maxy + 1):
            # Early exit if product already exceeds best
            if x * y >= best_product:
                continue

            lucky_count = count_lucky(x, y)

            if lucky_count >= w:
                current_product = x * y
                if current_product < best_product:
                    best_product = current_product
                    best_result = f"{x} {y}"
                elif current_product == best_product and best_result is None:
                    best_result = f"{x} {y}"

    return '-1' if best_result is None else best_result


