    for types in ice_cream_at:
        total_types.update(types)

    # If no ice cream types, return 0
    if not total_types:
        return f"0\n" + ' '.join([''] * m) + ' '

    # Calculate chromatic number: max clique size among all vertices
    # This is the maximum number of ice creams at any single vertex
    chromatic = 0
    for types in ice_cream_at:
        chromatic = max(chromatic, len(types))

    if chromatic == 0:
        chromatic = 1

    # Greedy coloring: for each ice cream type, assign the smallest available color
    # that doesn't conflict with types at the same vertex
    color_assignment = {}

    # Process ice cream types in order
    for ice_type in range(1, m + 1):
        # Find all vertices where this ice cream appears
        vertices = []
        for v in range(n):
            if ice_type in ice_cream_at[v]:
                vertices.append(v)

