def solution(input_string):
    n, l, r = map(int, input_string.split())

    if n == 1:
        return str(r - l + 1)

    if n == 2:
        return str((r - l + 1) * (r - l))

    # For n >= 3, enumerate all valid ratios p/q
    result = 0

    # Maximum q needed: q^(n-1) <= r, so q <= r**(1/(n-1))
    max_q = int(r ** (1.0 / (n - 1))) + 2

    for q in range(1, max_q + 1):
        q_pow = q ** (n - 1)
        if q_pow > r:
            break

        # For each q, enumerate p values
        # Need p != q for distinct elements
        # We'll handle both p > q (increasing) and p < q (decreasing)

        max_p = r
        for p in range(1, max_p + 1):
            if p == q:
                continue

            # Check gcd(p, q) == 1
            if gcd(p, q) != 1:
                continue

            p_pow = p ** (n - 1)

            # For valid progression, all terms must be in [l, r]
            # Terms are: a1, a1*(p/q), a1*(p/q)^2, ..., a1*(p/q)^(n-1)

            if p > q:
                # Increasing progression
                # max term: a1 * p^(n-1) / q^(n-1) <= r
                # => a1 <= r * q^(n-1) / p^(n-1)
                # Also a1 >= l

                max_val = r * q_pow // p_pow
                if max_val < l:
                    continue

                # a1 must be in [l, max_val] and divisible by q^(n-1)
                min_valid = (l + q_pow - 1) // q_pow
                max_valid = max_val // q_pow

                if min_valid <= max_valid:
                    result += (max_valid - min_valid + 1)
            else:
                # p < q, decreasing progression
                # min term: a1 * p^(n-1) / q^(n-1) >= l
                # => a1 >= ceil(l * q^(n-1) / p^(n-1))
                # Also a1 <= r

                min_val = (l * q_pow + p_pow - 1) // p_pow
                if min_val > r:
                    continue

                # a1 must be in [min_val, r] and divisible by q^(n-1)
                min_valid = min_val
                max_valid = r // q_pow

                if min_valid <= max_valid:
                    result += (max_valid - min_valid + 1)

        # Optimization: once p gets too large, don't continue
        if p ** (n - 1) > r * q ** (n - 1) * 10:
            break

    return str(result)


