def solution(s):
    lines = s.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    min_time = float('inf')

    for T in range(1, n + 1):
        # Try each time t from 1 to n
        for t in range(1, n + 1):
            # Krakozyabra is at position p = t + 1 (or we need to check he can reach it)
            # Actually, at time t, Krakozyabra is at position t + 1
            # But we need to ensure he can reach it safely

            # Check if Krakozyabra can safely be at position t+1 at time t
            # For each position j from 1 to t+1 (inclusive, since Krakozyabra needs to pass through/stop at t+1),
            # the icicle must NOT fall at or before time t (strictly after time t to allow passage)
            blocked = False
            p = t + 1

            if p <= n:
                for j in range(1, p + 1):
                    ft = abs(j - T) + a[j - 1]
                    if ft <= t:
                        blocked = True
                        break
            else:
                # Krakozyabra would be out of bounds, can't entrap
                continue

            if blocked:
                continue

            # Now check entrapment at position p = t + 1
            # Need fallen icICLE to the left (positions < p) and to the right (positions > p)
            left_fallen = False
            for j in range(1, p):
                ft = abs(j - T) + a[j - 1]
                if ft <= t:
                    left_fallen = True
                    break

            if left_fallen:
                right_fallen = False
                for j in range(p + 1, n + 1):
                    ft = abs(j - T) + a[j - 1]
                    if ft <= t:
                        right_fallen = True
                        break

                if right_fallen:
                    min_time = min(min_time, t)
                    # Since we want minimum time and t increases, we can break early for this T
                    break

    if min_time == float('inf'):
        return "-1\n"
    return f"{min_time}\n"

# This problem asks us to find x that maximizes sum(x % a_i) for all i in [1, n]
# Based on the examples, we interpret f(x, 1) as the sum of all x % a_i

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "0"

    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    if n == 0:
        return "0"

    def f(x):
        return sum(x % val for val in a)

    max_a = max(a)
    ans = 0

    candidates = set()

    # Add small x values to check
    for x in range(min(50000, max_a + 500)):
        candidates.add(x)

    # Add values near multiples of each a_i
    for val in a:
        k = 0
        while k * val < max_a * 5000:
            for offset in range(-20, 21):
                candidates.add(k * val + offset)
            k += 1

    for x in candidates:
        if x < 0:
            continue
        val = f(x)
        ans = max(ans, val)

    return str(ans)

def solution(input_str):
    k, x, n, m = map(int, input_str.strip().split())

    def count_ac(s):
        return s.count("AC")

    def generate_sk(s1, s2, k):
        if k == 1:
            return s1
        if k == 2:
            return s2
        a, b = s1, s2
        for _ in range(k - 2):
            a, b = b, a + b
        return b

    # For small cases, try specific patterns first
    pattern_s1 = [
        "A" * n,
        "AC" * (n // 2) + ("A" if n % 2 else "")[:n],
        "CA" * (n // 2) + ("C" if n % 2 else "")[:n],
        "B" * n,
        "AB" * (n // 2) + ("A" if n % 2 else "")[:n],
        "AC" * (n // 3) + "A" * (n - n // 3),
    ]
    pattern_s2 = [
        "A" * m,
        "AC" * (m // 2) + ("A" if m % 2 else "")[:m],
        "CA" * (m // 2) + ("C" if m % 2 else "")[:m],
        "B" * m,
        "AB" * (m // 2) + ("A" if m % 2 else "")[:m],
    ]

    for s1 in pattern_s1:
        for s2 in pattern_s2:
            s_k = generate_sk(s1, s2, k)
            if len(s_k) > 10**6:
                continue
            if count_ac(s_k) == x:
                return s1 + "\n" + s2

    # Try base-only strings (only A and C)
    for end1 in ['A', 'C']:
        for start2 in ['C', 'A']:
            s1 = 'A' * n if end1 == 'A' else end1 + 'A' * (n - 1)
            s2 = 'C' * m if start2 == 'C' else start2 + 'C' * (m - 1)
            if len(s1) != n or len(s2) != m:
                continue
            s_k = generate_sk(s1, s2, k)
            if len(s_k) > 10**6:
                continue
            if count_ac(s_k) == x:
                return s1 + "\n" + s2

    return "Happy new year!\n"

