def multiply(A: List[List[int]], B: List[List[int]], mod: int) -> List[List[int]]:
    n = len(A)
    C = [[0] * len(B[0]) for _ in range(n)]
    for i in range(n):
        for k in range(len(B)):
            if A[i][k] == 0:
                continue
            for j in range(len(B[0])):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
    return C

def power(A: List[List[int]], p: int, mod: int) -> List[List[int]]:
    n = len(A)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1
    base = [row[:] for row in A]
    while p > 0:
        if p & 1:
            res = multiply(res, base, mod)
        base = multiply(base, base, mod)
        p >>= 1
    return res

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solution(input_text: str) -> str:
