    m, t, s = int(first_line[0]), int(first_line[1]), int(first_line[2])
    a = list(map(int, lines[1].split()))

    MOD = 1051131
    n = 2 * m

    # Generate all a[i] values modulo MOD
    for i in range(s, n):
        a.append((101 * a[i - s] + 10007) % MOD)

    # Build transition matrix T of size (2m) x (2m)
    # T[u-1][v-1] = gcd(u,v) for u != v
    # T[u-1][u-1] = 1 (stay at island)
    T = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            u, v = i + 1, j + 1
            if u == v:
                T[i][j] = 1
            else:
                T[i][j] = gcd(u, v)

    # Compute T^t
    Tt = power(T, t, MOD)

    # Compute ans[i] = sum(Tt[i][j] * a[j]) % MOD
    ans = [0] * n
    for i in range(n):
        val = 0
        for j in range(n):
            val = (val + Tt[i][j] * a[j]) % MOD
        ans[i] = val

    # XOR sum of all answers
    xor_sum = 0
    for val in ans:
        xor_sum ^= val

    return f"{xor_sum}\n"

