def count_components(n, i, j):
    # Union-find to count components
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    # Add constraints from I_i
    for x in range(i):
        union(x, n - i + x)

    # Add constraints from I_j
    for x in range(j):
        union(x, n - j + x)

    # Count components
    roots = set()
    for x in range(n):
        roots.add(find(x))

    return len(roots)

