        key = (r, c, current_balance)
        if key in memo:
            return memo[key]

        count = 0

        # Try moving right (place ')' to continue from previous)
        if c + 1 < m:
            # Current cell needs to maintain balance
            count += count_valid_completions(r, c + 1, current_balance - 1) if current_balance >= 1 else 0

        # Try moving down (place '(' to continue from previous)
        if r + 1 < n:
            count += count_valid_completions(r + 1, c, current_balance + 1)

        memo[key] = count
