import sys

MOD = 10**9 + 7

def solution(input_str: str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    q = int(lines[0])
    MAX_N = 1000000

    # Sieve to compute smallest prime factor for each number
    spf = list(range(MAX_N + 1))
    for i in range(2, int(MAX_N**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, MAX_N + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Precompute factorials for combinations up to ~2000000
    # We need C(r+a, a) where r <= 10^6, a <= log2(10^6) ≈ 20
    MAX_COMB = 1000050
    fact = [1] * MAX_COMB
    inv_fact = [1] * MAX_COMB

    for i in range(1, MAX_COMB):
        fact[i] = (fact[i-1] * i) % MOD

    inv_fact[MAX_COMB-1] = pow(fact[MAX_COMB-1], MOD-2, MOD)
    for i in range(MAX_COMB-2, -1, -1):
        inv_fact[i] = (inv_fact[i+1] * (i+1)) % MOD

    def nCr(n, r_val):
        if r_val < 0 or r_val > n:
            return 0
        num = fact[n]
        den = (inv_fact[r_val] * inv_fact[n-r_val]) % MOD
        return (num * den) % MOD

    # Precompute prime factorization exponents for all n up to MAX_N
    prime_exps = [[] for _ in range(MAX_N + 1)]

    for i in range(1, MAX_N + 1):
        temp = i
        exps = []
        while temp > 1:
            p = spf[temp]
            cnt = 0
            while temp % p == 0:
                temp //= p
                cnt += 1
            exps.append(cnt)
        prime_exps[i] = exps

    results = []

    for line in lines[1:]:
        if not line.strip():
            continue
        r, n = map(int, line.split())

        if n == 1:
            results.append('1')
            continue

        # f_r(n) = product of C(r + a, r) for each prime exponent a
        # = product of C(r + a, a)
        ans = 1
        for exp in prime_exps[n]:
            # C(r + exp, exp)
            if exp == 0:
                continue
            if r + exp >= MAX_COMB:
                # For large r, we use direct computation
                # C(r+exp, exp) = (r+exp)(r+exp-1)...(r+1) / exp!
                numerator = 1
                for k in range(1, exp + 1):
                    numerator = (numerator * (r + k)) % MOD

                # Compute exp! inverse
                if exp < 20:
                    denom = 1
                    for k in range(1, exp + 1):
                        denom = (denom * k) % MOD
                else:
                    denom = 1
                    for k in range(1, exp + 1):
                        denom = (denom * k) % MOD

                ans = (ans * numerator * pow(denom, MOD-2, MOD)) % MOD
            else:
                v = nCr(r + exp, exp)
                ans = (ans * v) % MOD

        results.append(str(ans))

    return '\n'.join(results)


