            if sum(s[0] for s in combo) == total_a and sum(s[1] for s in combo) == total_b:
                return list(combo)
        return None

    # For mixed, we need to be smarter - try combinations
    from itertools import combinations

    # Select subsets
    for a_combo in combinations(a_winning, a_wins):
        if sum(s[0] for s in a_combo) != total_a:
